#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────


# Wizard for "Refund Request raised and received Notifications (Feed only)"
# (dejongyeong/ai-hero-sw-factories#27). Creates and commits the
# refund-request-raised and refund-request-received workflows in Knock's
# Development environment, then confirms Knock can find both.
# Assumes the Knock keys are already in .env (scripts/knock-setup.sh).

RAISED_KEY="refund-request-raised"
RECEIVED_KEY="refund-request-received"
WORKFLOW_CATEGORY="refunds"
REQUIRED_KEYS=(KNOCK_SECRET_API_KEY KNOCK_PUBLIC_API_KEY KNOCK_SIGNING_KEY KNOCK_FEED_CHANNEL_ID)

# The trigger data app/lib/notify.server.ts sends for each workflow.
RAISED_DATA='{"refund_request_id":0,"actor_name":"Wizard probe","course_title":"Probe course","amount":"$0.00","url":"/admin/refund-requests?status=open#refund-request-0"}'
RECEIVED_DATA='{"refund_request_id":0,"course_title":"Probe course","url":"/courses/probe"}'

# probe_workflow KEY DATA: triggers the workflow in sandbox mode for an inline
# probe recipient, with the same data shape the app sends, so nothing is
# delivered. Prints the HTTP status and Knock's error code, if any.
probe_workflow() {
  local workflow="$1" data="$2" key body status code
  key=$(_existing KNOCK_SECRET_API_KEY) || { echo "no KNOCK_SECRET_API_KEY in $ENV_FILE"; return 0; }
  body=$(curl -s -w '\n%{http_code}' -X POST \
    "https://api.knock.app/v1/workflows/$workflow/trigger" \
    -H "Authorization: Bearer $key" \
    -H "Content-Type: application/json" \
    -d '{"recipients":[{"id":"cadence-wizard-probe","name":"Wizard probe"}],"data":'"$data"',"settings":{"sandbox_mode":true}}') \
    || { echo "curl failed"; return 0; }
  status=${body##*$'\n'}
  code=$(printf '%s' "${body%$'\n'*}" | grep -o '"code":"[^"]*"' | cut -d'"' -f4 || true)
  echo "$status $code"
}

# confirm_workflow KEY DATA: probes until Knock finds the workflow, or the
# human gives up.
confirm_workflow() {
  local workflow="$1" data="$2" result=""
  until result=$(probe_workflow "$workflow" "$data") && [[ "$result" == 200* ]]; do
    warn "Knock answered for $workflow: $result"
    [[ "$result" == *workflow_missing* ]] && note "Not committed yet, the key isn't exactly $workflow, or it's in another environment."
    confirm "Try again?" || { SKIPPED+=("Workflow $workflow not confirmed in Knock"); return 0; }
  done
  printf '  %s✓%s workflow %s is live in Development\n' "$GREEN" "$RESET" "$workflow"
}

run_wizard() {

TOTAL_STAGES=5

banner "Knock: set up the Refund Request raised and received workflows"

missing=()
for k in "${REQUIRED_KEYS[@]}"; do _existing "$k" >/dev/null || missing+=("$k"); done
if (( ${#missing[@]} )); then
  warn "$ENV_FILE is missing: ${missing[*]}"
  note "Run scripts/knock-setup.sh first, then come back to this wizard."
  exit 1
fi

stage "Create the Refund Request raised workflow"
open_url "https://dashboard.knock.app"
step "Environment switcher (top left): make sure you're in ${BOLD}Development${RESET}."
step "Open ${BOLD}Workflows${RESET} → ${BOLD}Create workflow${RESET}."
step "Name: ${BOLD}Refund Request raised${RESET}. Key: ${BOLD}$RAISED_KEY${RESET} (exactly this: the app triggers it by key)."
step "Categories: add ${BOLD}$WORKFLOW_CATEGORY${RESET}, then create it."
note "A Platform Admin can switch this one off, so leave its preference settings as they are."
note "Dashboard labels may differ slightly from these; the key and category are what matter."
pause "Press Enter once the workflow canvas is open"

stage "Add Refund Request raised's in-app Feed step, and commit"
step "In the canvas, add a channel step of type ${BOLD}In-app feed${RESET}."
step "Pick the same Feed channel comment-reply uses (its id is KNOCK_FEED_CHANNEL_ID in .env)."
step "Edit its template. Choose the ${BOLD}Standard${RESET} variant (the whole row is the link)."
step "Markdown body:"
say  "    ${BOLD}**{{ data.actor_name }}** requested a refund for **{{ data.course_title }}** ({{ data.amount }})${RESET}"
step "Action URL: replace the default with ${BOLD}{{ vars.app_url }}{{ data.url }}${RESET}"
note "data.url is /admin/refund-requests?status=<status>#refund-request-<id>; vars.app_url supplies the host."
note "Cadence's bell builds its own sentence from the data, but the step still needs a template."
step "Don't add an email step: the \"Refund requested\" email still goes out through the app's mailer."
step "Save the step, then click ${BOLD}Commit${RESET} (top right) and commit to Development."
pause "Press Enter once it's committed"
say "Checking Knock can find it (sandbox run, nothing is sent)…"
confirm_workflow "$RAISED_KEY" "$RAISED_DATA"
pause

stage "Create the Refund Request received workflow"
step "Back in ${BOLD}Workflows${RESET} (still in ${BOLD}Development${RESET}) → ${BOLD}Create workflow${RESET}."
step "Name: ${BOLD}Refund Request received${RESET}. Key: ${BOLD}$RECEIVED_KEY${RESET}."
step "Categories: add ${BOLD}$WORKFLOW_CATEGORY${RESET}, then create it."
step "Open the workflow's ${BOLD}Settings${RESET} and turn on ${BOLD}Override recipient preferences${RESET}."
note "That marks it as always sent: switching off the $WORKFLOW_CATEGORY category won't stop it."
note "If the label differs, look for the setting that ignores recipient preferences for this workflow."
pause "Press Enter once the setting is saved and the canvas is open"

stage "Add Refund Request received's in-app Feed step, and commit"
step "Add a channel step of type ${BOLD}In-app feed${RESET}, on the same Feed channel."
step "Edit its template. Choose the ${BOLD}Standard${RESET} variant."
step "Markdown body:"
say  "    ${BOLD}We've got your refund request for **{{ data.course_title }}**${RESET}"
step "Action URL: ${BOLD}{{ vars.app_url }}{{ data.url }}${RESET}"
note "data.url is the course page, /courses/<slug>."
step "Don't add an email step."
step "Save the step, then click ${BOLD}Commit${RESET} and commit to Development."
pause "Press Enter once it's committed"
say "Checking Knock can find both workflows (sandbox runs, nothing is sent)…"
confirm_workflow "$RAISED_KEY" "$RAISED_DATA"
confirm_workflow "$RECEIVED_KEY" "$RECEIVED_DATA"
pause

finish
say "Next: run ${BOLD}npm run dev${RESET}, raise a Refund Request on a course as a Student, then"
say "switch to a Platform Admin in the DevUI panel: the bell shows Refund Request raised, and"
say "clicking it lands on the highlighted card in the Open queue. Back as the Student, the"
say "bell shows Refund Request received, linking to the course. Exactly one"
say "\"Refund requested\" email still goes out, through the app's mailer."
printf '\n'
}

run_wizard "$@"; exit
